"use server";

/**
 * VM move — admin server actions. This is the interface the admin ops UI
 * (agent A2's app/admin/ops) calls; the contract is documented in
 * docs/VM-MOVE.md. Every mutation is gated by requireArea("fleet"), audited,
 * idempotent where it can be, and enqueues a Job — the web app never touches
 * Proxmox, ZFS or OVH directly (that is worker/vm-move.ts's job).
 */
import { z } from "zod";
import type { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { recordAudit } from "@/lib/audit";
import { withServerJobLock } from "@/lib/job-guard";
import { buildMovePlan } from "./preflight";
import { moveCandidatesForNode, type RealUsageByVmid } from "./candidates";
import type { MoveCandidate, MovePlan } from "./types";

const idSchema = z.string().min(5).max(64).regex(/^[a-z0-9]+$/i);

export type RequestVmMoveInput = {
  serverId: string;
  targetNodeId: string;
  /** Preflight only: builds + stores the plan, touches nothing. */
  dryRun?: boolean;
  /** Free-text operator reason, stored on the VmMove row and in the audit log. */
  reason?: string;
  /** Accept that the VM's Proxmox snapshots are not carried over. */
  allowDropSnapshots?: boolean;
};

export type RequestVmMoveResult = { ok: true; vmMoveId: string; jobId: string } | { ok: false; error: string };

/**
 * Plan (dryRun) or execute a move. Returns the VmMove id to poll with
 * getVmMove(); the job runs on the worker and the row's `phase`/`log`/`plan`
 * fill in as it goes. Refused when another job or move is in flight for the
 * server (same per-server lock every other server action uses).
 */
export async function requestVmMove(input: RequestVmMoveInput): Promise<RequestVmMoveResult> {
  const admin = await requireArea("fleet");
  const parsed = z
    .object({
      serverId: idSchema,
      targetNodeId: idSchema,
      dryRun: z.boolean().optional(),
      reason: z.string().max(500).optional(),
      allowDropSnapshots: z.boolean().optional(),
    })
    .safeParse(input);
  if (!parsed.success) return { ok: false, error: "Invalid request." };
  const { serverId, targetNodeId, dryRun = false, reason, allowDropSnapshots = false } = parsed.data;

  const server = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, vmid: true, nodeId: true, status: true } });
  if (!server) return { ok: false, error: "Server not found." };
  const target = await db.node.findUnique({ where: { id: targetNodeId }, select: { id: true, name: true, enabled: true } });
  if (!target) return { ok: false, error: "Target node not found." };
  if (server.nodeId === target.id) return { ok: false, error: "That is already the server's node." };
  if (!server.vmid) return { ok: false, error: "The server has no VM yet." };

  const sourceNodeId = server.nodeId ?? (await db.node.findFirst({ where: { isPrimary: true }, select: { id: true } }))?.id;
  if (!sourceNodeId) return { ok: false, error: "The server has no node." };

  const result = await withServerJobLock(serverId, async (tx) => {
    const pending = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (pending > 0) return { ok: false as const, error: "Another job is already in flight for this server." };
    const running = await tx.vmMove.count({ where: { serverId, status: "RUNNING" } });
    if (running > 0) return { ok: false as const, error: "A move is already running for this server." };
    const move = await tx.vmMove.create({
      data: {
        serverId,
        sourceNodeId,
        targetNodeId: target.id,
        sourceVmid: server.vmid!,
        targetVmid: 0, // allocated at preflight
        dryRun,
        reason: reason?.trim() || null,
        requestedById: admin.id,
        checkpoints: (allowDropSnapshots ? { allowDropSnapshots: true } : {}) as Prisma.InputJsonValue,
      },
      select: { id: true },
    });
    const job = await tx.job.create({ data: { type: "VM_MOVE", serverId, payload: { vmMoveId: move.id } }, select: { id: true } });
    return { ok: true as const, vmMoveId: move.id, jobId: job.id };
  });
  if (result.ok) {
    await recordAudit(admin.id, dryRun ? "server.vm_move.plan" : "server.vm_move.request", `${server.hostname} → ${target.name} move=${result.vmMoveId}${reason ? ` reason=${reason.trim().slice(0, 120)}` : ""}`);
  }
  return result;
}

/** Preflight WITHOUT creating a VmMove row or a job — for a live "what would happen" panel. Read-only. */
export async function previewVmMove(serverId: string, targetNodeId: string, allowDropSnapshots = false): Promise<{ ok: true; plan: MovePlan } | { ok: false; error: string }> {
  await requireArea("fleet");
  if (!idSchema.safeParse(serverId).success || !idSchema.safeParse(targetNodeId).success) return { ok: false, error: "Invalid request." };
  try {
    const plan = await buildMovePlan({ serverId, targetNodeId, allowDropSnapshots });
    return { ok: true, plan };
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

/** Destroy the stopped source VM of a DONE move (after keepSourceUntil unless `force`). */
export async function requestVmMoveCleanup(vmMoveId: string, opts?: { force?: boolean }): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
  const admin = await requireArea("fleet");
  if (!idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
  const move = await db.vmMove.findUnique({ where: { id: vmMoveId }, select: { id: true, serverId: true, status: true, keepSourceUntil: true, server: { select: { hostname: true } } } });
  if (!move) return { ok: false, error: "Move not found." };
  if (move.status !== "DONE") return { ok: false, error: `Only a DONE move can be cleaned up (this one is ${move.status}).` };
  if (move.keepSourceUntil && move.keepSourceUntil.getTime() > Date.now() && !opts?.force) {
    return { ok: false, error: `The source VM is kept until ${move.keepSourceUntil.toISOString().slice(0, 10)}; pass force to override.` };
  }
  const existing = await db.job.findFirst({ where: { type: "VM_MOVE_CLEANUP", status: { in: ["QUEUED", "RUNNING"] }, payload: { path: ["vmMoveId"], equals: vmMoveId } }, select: { id: true } });
  if (existing) return { ok: true, jobId: existing.id };
  const job = await db.job.create({ data: { type: "VM_MOVE_CLEANUP", serverId: move.serverId, payload: { vmMoveId, force: !!opts?.force } }, select: { id: true } });
  await recordAudit(admin.id, "server.vm_move.cleanup", `${move.server.hostname} move=${vmMoveId}${opts?.force ? " force" : ""}`);
  return { ok: true, jobId: job.id };
}

/** Ask a RUNNING move (not yet committed) to roll back at its next step. */
export async function requestVmMoveRollback(vmMoveId: string): Promise<{ ok: true; jobId: string } | { ok: false; error: string }> {
  const admin = await requireArea("fleet");
  if (!idSchema.safeParse(vmMoveId).success) return { ok: false, error: "Invalid request." };
  const move = await db.vmMove.findUnique({ where: { id: vmMoveId }, select: { id: true, serverId: true, status: true, checkpoints: true, server: { select: { hostname: true } } } });
  if (!move) return { ok: false, error: "Move not found." };
  if (move.status !== "RUNNING") return { ok: false, error: `Only a RUNNING move can be rolled back (this one is ${move.status}).` };
  const cp = (move.checkpoints as Record<string, unknown> | null) ?? {};
  if (cp.committedAt) return { ok: false, error: "This move is already committed — the database points at the new node; roll forward instead." };
  await db.vmMove.update({ where: { id: vmMoveId }, data: { checkpoints: { ...cp, rollbackRequested: true } as Prisma.InputJsonValue } });
  // The running job notices the flag at its next phase boundary; if the job
  // is between attempts (QUEUED), the re-queued job picks it up immediately.
  const job = await db.job.findFirst({ where: { type: "VM_MOVE", payload: { path: ["vmMoveId"], equals: vmMoveId } }, orderBy: { createdAt: "desc" }, select: { id: true, status: true } });
  let jobId = job?.id ?? "";
  if (!job || job.status === "DONE" || job.status === "FAILED") {
    jobId = (await db.job.create({ data: { type: "VM_MOVE", serverId: move.serverId, payload: { vmMoveId } }, select: { id: true } })).id;
  }
  await recordAudit(admin.id, "server.vm_move.rollback", `${move.server.hostname} move=${vmMoveId}`);
  return { ok: true, jobId };
}

export async function getVmMove(vmMoveId: string) {
  await requireArea("fleet");
  if (!idSchema.safeParse(vmMoveId).success) return null;
  return db.vmMove.findUnique({
    where: { id: vmMoveId },
    include: { server: { select: { id: true, hostname: true, status: true, vmid: true, nodeId: true } } },
  });
}

export async function listVmMoves(opts?: { serverId?: string; limit?: number }) {
  await requireArea("fleet");
  return db.vmMove.findMany({
    where: opts?.serverId ? { serverId: opts.serverId } : undefined,
    orderBy: { createdAt: "desc" },
    take: Math.min(200, Math.max(1, opts?.limit ?? 50)),
    include: { server: { select: { id: true, hostname: true, status: true } } },
  });
}

/** Ranked offload candidates for a node (lib/vm-move/plan.ts rankMoveCandidates). */
export async function listMoveCandidates(nodeId: string, real?: RealUsageByVmid): Promise<MoveCandidate[]> {
  await requireArea("fleet");
  if (!idSchema.safeParse(nodeId).success) return [];
  return moveCandidatesForNode(nodeId, real);
}
/**
 * VM move — shared types for the planner (lib/vm-move/plan.ts, pure), the
 * preflight (lib/vm-move/preflight.ts, reads DB/Proxmox/OVH), the worker
 * handler (worker/vm-move.ts) and the admin-facing server actions
 * (lib/vm-move/actions.ts). Everything here is plain data so it can be stored
 * verbatim on `VmMove.plan` / `VmMove.checkpoints` (Json columns) and read back
 * by a resumed job or the admin ops UI.
 *
 * See docs/VM-MOVE.md for the interface contract and docs/PRIMARY-OFFLOAD-PLAN.md
 * for the operational plan this engine exists to execute.
 */

/** Phases, in execution order. `VmMove.phase` holds the phase currently being
 *  executed (or the last completed one once DONE). Resume = find the first
 *  phase not yet checkpointed and continue from there. */
export const MOVE_PHASES = [
  "PREFLIGHT", // build + persist the plan (the only phase a dry run executes)
  "SNAPSHOT_LIVE", // consistent (guest-agent fs-freeze) Proxmox snapshot of the running source
  "SEND_FULL", // full zfs stream of that snapshot → target dataset vm-<targetVmid>-disk-0 (source still running)
  "STOP_SOURCE", // graceful shutdown of the source VM — start of the dark window
  "SEND_INCREMENTAL", // zfs snapshot of the now-quiescent source + incremental stream (small)
  "CREATE_TARGET", // target VM config (API) + move-safe cloud-init vendor snippet
  "MOVE_IP", // dedicated-IP servers only: OVH IP move + new Virtual MAC on the target (last reversible step)
  "START_TARGET", // start + verify guest agent / SSH
  "COMMIT", // DB cutover (nodeId, vmid, ipAddress), NAT reconcile, DNS resync, notices, audit
  "DONE",
] as const;
export type MovePhase = (typeof MOVE_PHASES)[number];

/** How the server reaches the internet today, and how it will after the move. */
export type MoveAddressing =
  | {
      kind: "DEDICATED";
      /** The public IPv4 the customer already uses — unchanged by the move. */
      address: string;
      /** Provider gateway on the source and target nodes (OVH: <node /24>.254). */
      sourceGateway: string;
      targetGateway: string;
      /** Provider service names the IP is routed FROM and TO (OVH `serviceName`). */
      sourceService: string;
      targetService: string;
      /** Virtual MAC currently bound on the source node (deleted at cleanup). */
      sourceVirtualMac: string | null;
    }
  | {
      kind: "NAT";
      sourcePrivateIp: string;
      /** Allocated at COMMIT from the target node's own /24; planned here for display. */
      targetPrivateIpPlanned: string;
      targetGateway: string;
      /** SSH port + every PortForward public port are globally unique and keep their numbers. */
      sshPort: number | null;
      forwardPorts: number[];
      sourcePublicIp: string;
      targetPublicIp: string;
    };

/** One preflight check. `blocking` checks must all pass for a real move. */
export type PreflightCheck = {
  id: string;
  ok: boolean;
  blocking: boolean;
  detail: string;
};

export type NodeCapacityFacts = {
  nodeId: string;
  name: string;
  region: string;
  /** Host RAM really available right now (Proxmox node status), in MB. */
  realAvailRamMB: number;
  realTotalRamMB: number;
  /** Σ plan RAM of live servers vs the node's configured capacity, in MB. */
  committedRamMB: number;
  capacityRamMB: number;
  /** VM-disk pool free bytes (storageNvme). */
  poolFreeBytes: number;
  poolTotalBytes: number;
  cpuThreads: number;
  committedVcpu: number;
  /** Proxmox-reported 0..1 CPU load at preflight time. */
  cpuLoad: number;
};

export type MovePlan = {
  version: 1;
  serverId: string;
  hostname: string;
  sourceNodeId: string;
  sourceNodeName: string;
  targetNodeId: string;
  targetNodeName: string;
  sourceVmid: number;
  targetVmid: number;
  /** Plan RAM / vCPU / disk the server is entitled to (what moves with it). */
  planRamMB: number;
  planVcpu: number;
  diskSizeGB: number;
  /** Bytes the source zvol actually holds (zfs `used`) — the real transfer size. */
  sourceUsedBytes: number;
  /** Source dataset (pool path, e.g. data/vms/vm-109-disk-0) and target dataset. */
  sourceDataset: string;
  targetDataset: string;
  /** Proxmox storage id on each side (e.g. vmdata) and the target's snippet storage. */
  sourceStorage: string;
  targetStorage: string;
  targetSnippetStorage: string;
  /** Bridge the target NIC attaches to: vmbr0 (dedicated) or the node's NAT bridge. */
  targetBridge: string;
  addressing: MoveAddressing;
  /** Source VM config keys carried over verbatim (cores, memory, balloon, cpu, agent, boot, ostype, scsihw, ...). */
  carriedConfig: Record<string, string>;
  target: NodeCapacityFacts;
  checks: PreflightCheck[];
  /** True iff every blocking check passed. */
  ok: boolean;
  /** Estimated dark window in seconds (shutdown + incremental send + boot + verify). */
  estimatedDowntimeSec: number;
  /** Estimated full-stream duration in seconds at the assumed link rate (source stays up). */
  estimatedFullSendSec: number;
  createdAt: string;
};

/** Facts written as each phase completes, so a resumed job never redoes a
 *  destructive or expensive step. All optional: absent = not done. */
export type MoveCheckpoints = {
  liveSnapshotName?: string; // Proxmox snapshot name on the source (SNAPSHOT_LIVE)
  fullSentAt?: string; // SEND_FULL finished
  sourceStoppedAt?: string; // STOP_SOURCE finished (dark window opened)
  incrementalSnapshotName?: string; // zfs-only snapshot on the source (SEND_INCREMENTAL)
  incrementalSentAt?: string;
  targetVmCreated?: boolean; // CREATE_TARGET
  targetSnippetWritten?: boolean;
  ipMovedAt?: string; // MOVE_IP: OVH task finished, IP now routed to the target service
  ipMoveTaskId?: number;
  targetVirtualMac?: string;
  targetStartedAt?: string; // START_TARGET
  targetVerified?: boolean;
  committedAt?: string; // COMMIT
  previousIpAddress?: string | null; // for rollback of the DB cutover
  previousSshPort?: number | null;
  sourceOnbootDisabled?: boolean;
  rollback?: { startedAt: string; finishedAt?: string; steps: string[]; errors: string[] };
};

export type MoveLogLine = { at: string; phase: string; msg: string };

/** The exact payload a VM_MOVE Job carries. Kept tiny on purpose — the VmMove
 *  row (by id) is the source of truth; the job is just the worker's handle. */
export type VmMoveJobPayload = {
  vmMoveId: string;
};

/** Payload of a VM_MOVE_CLEANUP job. */
export type VmMoveCleanupJobPayload = {
  vmMoveId: string;
};

/** Candidate classes used by the offload plan (docs/PRIMARY-OFFLOAD-PLAN.md). */
export type MoveClass =
  | "A_DEDICATED_IP" // move + carry the public IP: no customer-visible address change
  | "B_NAT" // public IP changes (same ports); Minecraft subdomains are repointed via SYNC_GAME_DNS
  | "C_MUST_STAY"; // company infrastructure / attached volumes / no vmid

export type MoveCandidate = {
  serverId: string;
  hostname: string;
  vmid: number | null;
  nodeId: string | null;
  klass: MoveClass;
  reasons: string[];
  planRamMB: number;
  planVcpu: number;
  diskGB: number;
  /** Real RSS the kvm process holds right now, when the caller has it (MB). */
  realRssMB: number | null;
  /** 0..100 relief score used for ranking — see rankMoveCandidates. */
  relief: number;
  /** 0..100 risk score (higher = riskier). */
  risk: number;
  /** Customer-visible impact summary. */
  impact: string;
  /** Combined rank score — higher moves first. */
  score: number;
};
/**
 * VM move — candidate inventory for one node (the admin ops "offload" view and
 * docs/PRIMARY-OFFLOAD-PLAN.md). Reads the DB, optionally merges real per-VM
 * resource usage the caller measured (kvm RSS / CPU%), and hands everything to
 * the pure ranker in lib/vm-move/plan.ts.
 */
import { db } from "../db";
import { rankMoveCandidates, type CandidateInput } from "./plan";
import type { MoveCandidate } from "./types";

export type RealUsageByVmid = Record<number, { rssMB: number; cpuPct: number }>;

export async function moveCandidatesForNode(nodeId: string, real?: RealUsageByVmid): Promise<MoveCandidate[]> {
  const servers = await db.server.findMany({
    where: { nodeId, status: { notIn: ["DELETING"] } },
    select: {
      id: true,
      hostname: true,
      vmid: true,
      nodeId: true,
      status: true,
      isFree: true,
      autoRenew: true,
      expiresAt: true,
      subdomain: true,
      plan: { select: { ramMB: true, cpuCores: true, diskGB: true } },
      gamePlan: { select: { ramMB: true, cpuCores: true, diskGB: true, gameFamily: true } },
      dedicatedIp: { select: { address: true, purpose: true } },
      _count: { select: { portForwards: true, volumes: true } },
    },
    orderBy: { hostname: "asc" },
  });
  const inputs: CandidateInput[] = servers.map((s) => {
    const usage = s.vmid ? real?.[s.vmid] : undefined;
    return {
      serverId: s.id,
      hostname: s.hostname,
      vmid: s.vmid,
      nodeId: s.nodeId,
      status: s.status,
      planRamMB: s.gamePlan?.ramMB ?? s.plan.ramMB,
      planVcpu: s.gamePlan?.cpuCores ?? s.plan.cpuCores,
      diskGB: s.gamePlan?.diskGB ?? s.plan.diskGB,
      hasDedicatedIp: !!s.dedicatedIp,
      internalIp: s.dedicatedIp?.purpose === "INTERNAL",
      isFree: s.isFree,
      attachedVolumes: s._count.volumes,
      subdomain: s.subdomain,
      forwardCount: s._count.portForwards,
      gameFamily: s.gamePlan?.gameFamily ?? null,
      realRssMB: usage?.rssMB ?? null,
      realCpuPct: usage?.cpuPct ?? null,
      daysToExpiry: s.expiresAt ? Math.floor((s.expiresAt.getTime() - Date.now()) / 86_400_000) : null,
      autoRenew: s.autoRenew,
      companyInfra: false,
    };
  });
  return rankMoveCandidates(inputs);
}

