+enum VmMoveStatus {
+  PLANNED // dry-run finished, or a real move queued but not yet started
+  RUNNING
+  DONE // cutover committed; source VM kept STOPPED until VM_MOVE_CLEANUP
+  ROLLED_BACK // a phase before commit failed; source running again, target removed
+  FAILED // rollback itself did not fully succeed — needs a human (see `error`)
+  CLEANED // source VM destroyed by VM_MOVE_CLEANUP
+}
+
+/// One VM move (server X from node A to node B) — the durable, resumable state
+/// behind the VM_MOVE job (worker/vm-move.ts). A Job row alone can't hold this:
+/// jobs retry from scratch, while a move must resume from its last completed
+/// phase (a 50 GB disk already streamed must not be streamed again), keep a
+/// rollback inventory (what exists on the target so far, which IP was moved),
+/// and survive long after the job is DONE so the explicit cleanup step days
+/// later knows exactly which stopped source VM it may destroy. `plan` is the
+/// preflight output (lib/vm-move/types.ts MovePlan), `checkpoints` the per-phase
+/// facts a resume needs (target VM created? snapshot names? IP moved?), `log`
+/// an append-only list of timestamped lines for the admin UI.
+model VmMove {
+  id              String       @id @default(cuid())
+  serverId        String
+  server          Server       @relation(fields: [serverId], references: [id], onDelete: Cascade)
+  sourceNodeId    String
+  targetNodeId    String
+  sourceVmid      Int
