+  // one — see lib/vm-move/plan.ts pickMoveTargetVmid). Reserved for the move's
+  // lifetime by being read back into every later allocation's "taken" set.
+  targetVmid      Int
+  status          VmMoveStatus @default(PLANNED)
+  phase           String       @default("PREFLIGHT")
+  dryRun          Boolean      @default(false)
+  reason          String?
+  requestedById   String?
+  plan            Json?
+  checkpoints     Json?
+  log             Json?
+  error           String?
+  // True when the customer's public address changed (NAT server moved to a
+  // node with a different public IP) — the only case a customer notice is sent.
+  addressChanged  Boolean      @default(false)
+  keepSourceUntil DateTime?
+  sourceCleanedAt DateTime?
+  startedAt       DateTime?
+  finishedAt      DateTime?
+  createdAt       DateTime     @default(now())
+  updatedAt       DateTime     @updatedAt
+
+  @@index([serverId])
+  @@index([status])
+}
+
