// ---------------------------------------------------------------------------
// Capacity
// ---------------------------------------------------------------------------

/** RAM a target host must still have REALLY available after the moved VM's
 *  full plan RAM is counted (the hypervisor, ZFS metadata, the agent and page
 *  cache all need room; a node with less than this is one burst from swap). */
export const TARGET_REAL_RAM_RESERVE_MB = Number(process.env.VM_MOVE_TARGET_RESERVE_MB ?? 4096);
/** Pool must keep this fraction free after the moved disk lands (ZFS
 *  performance collapses past ~80-85% full). */
export const TARGET_POOL_MIN_FREE_RATIO = 0.15;
/** Committed-RAM ceiling on the target after the move, as % of
 *  Node.capacityRamMB. Default 100: a move may fill a node up to the capacity
 *  the platform itself promises, never past it — real usage (above) is the
 *  other, independent gate. Lower it (e.g. 90, the scheduler's "critical")
 *  to keep provisioning headroom on the target. */
export const TARGET_COMMITTED_CRIT_PCT = Number(process.env.VM_MOVE_COMMITTED_MAX_PCT ?? 100);

export function capacityChecks(target: NodeCapacityFacts, planRamMB: number, planVcpu: number, usedBytes: number, diskSizeGB: number): PreflightCheck[] {
  const out: PreflightCheck[] = [];

  const availAfter = target.realAvailRamMB - planRamMB;
  out.push({
    id: "target-real-ram",
    ok: availAfter >= TARGET_REAL_RAM_RESERVE_MB,
    blocking: true,
    detail:
      `${target.name}: ${(target.realAvailRamMB / 1024).toFixed(1)} GB really available now, ` +
      `${(planRamMB / 1024).toFixed(1)} GB plan RAM moving in → ${(availAfter / 1024).toFixed(1)} GB left ` +
      `(needs ≥ ${(TARGET_REAL_RAM_RESERVE_MB / 1024).toFixed(1)} GB)`,
  });

  const committedAfterPct = target.capacityRamMB > 0 ? ((target.committedRamMB + planRamMB) / target.capacityRamMB) * 100 : 100;
  out.push({
    id: "target-committed-ram",
    ok: committedAfterPct < TARGET_COMMITTED_CRIT_PCT,
    blocking: true,
    detail: `${target.name}: committed ${(target.committedRamMB / 1024).toFixed(0)} → ${((target.committedRamMB + planRamMB) / 1024).toFixed(0)} GB of ${(target.capacityRamMB / 1024).toFixed(0)} GB (${committedAfterPct.toFixed(0)}%, limit ${TARGET_COMMITTED_CRIT_PCT}%)`,
  });

  // The zvol is sparse: what lands is roughly what the source really holds
  // (plus snapshot churn); the pool must still stay comfortably non-full.
  const freeAfter = target.poolFreeBytes - usedBytes;
  const freeAfterRatio = target.poolTotalBytes > 0 ? freeAfter / target.poolTotalBytes : 0;
  out.push({
    id: "target-pool-space",
    ok: freeAfter > 0 && freeAfterRatio >= TARGET_POOL_MIN_FREE_RATIO,
    blocking: true,
    detail: `${target.name}: pool ${(target.poolFreeBytes / 2 ** 30).toFixed(0)} GB free, disk really holds ${(usedBytes / 2 ** 30).toFixed(1)} GB (provisioned ${diskSizeGB} GB) → ${(freeAfter / 2 ** 30).toFixed(0)} GB free after (${(freeAfterRatio * 100).toFixed(0)}%, needs ≥ ${TARGET_POOL_MIN_FREE_RATIO * 100}%)`,
  });

  // vCPU is normally oversold; warn (not block) past 4x threads or when the
  // target is already busy.
  const vcpuAfter = target.committedVcpu + planVcpu;
  const ratio = target.cpuThreads > 0 ? vcpuAfter / target.cpuThreads : 99;
  out.push({
    id: "target-cpu",
    ok: ratio <= 4 && target.cpuLoad < 0.7,
    blocking: false,
    detail: `${target.name}: ${vcpuAfter} vCPU on ${target.cpuThreads} threads after (${ratio.toFixed(1)}x), load ${(target.cpuLoad * 100).toFixed(0)}% now`,
  });

  return out;
}

