/** Shape of OVH `GET /ip/{ip}/move` (ip.Destinations). */
export type OvhMoveDestinations = { dedicatedServer?: Array<{ service: string; nexthop?: string[] }> };

/**
 * May this IP be moved to `targetService`? OVH only lists destinations in the
 * same campus (a Singapore failover IP lists the three SGP boxes and NOT
 * nxeon-bhs1 — confirmed live 2026-10-01). This is the authoritative
 * same-zone check; the Node.region equality check is the cheap pre-filter.
 * A wrong-zone move is simply impossible through this path rather than
 * "possible but unusable".
 */
export function ipMoveDestinationAllowed(dest: OvhMoveDestinations | null | undefined, targetService: string): boolean {
  const list = dest?.dedicatedServer ?? [];
  return list.some((d) => d?.service === targetService);
}

// ---------------------------------------------------------------------------
// Estimates
// ---------------------------------------------------------------------------

/** Assumed sustained inter-node rate for the stream (bytes/s). OVH SGP boxes
 *  share a 1 Gbit/s uplink; zstd + the source's load make ~60 MB/s a sober
 *  planning figure. Override via env for a measured value. */
export async function nodeCapacityFacts(node: MoveNode, conn: PveClient, excludeServerId?: string): Promise<NodeCapacityFacts> {
  const [status, storage, servers] = await Promise.all([
    conn.get(`/nodes/${conn.node}/status`),
    conn.get(`/nodes/${conn.node}/storage/${encodeURIComponent(node.storageNvme)}/status`),
    db.server.findMany({
      where: { nodeId: node.id, status: { notIn: ["DELETING"] }, ...(excludeServerId ? { id: { not: excludeServerId } } : {}) },
      select: { plan: { select: { ramMB: true, cpuCores: true } }, gamePlan: { select: { ramMB: true, cpuCores: true } } },
    }),
  ]);
  const committedRamMB = servers.reduce((s, r) => s + (r.gamePlan?.ramMB ?? r.plan.ramMB), 0);
  const committedVcpu = servers.reduce((s, r) => s + (r.gamePlan?.cpuCores ?? r.plan.cpuCores), 0);
  const total = Number(status?.memory?.total ?? 0);
  // Proxmox's `memory.used` already excludes reclaimable cache (it is
  // MemTotal − MemAvailable on PVE 8/9), so total − used ≈ MemAvailable.
  const used = Number(status?.memory?.used ?? 0);
  return {
    nodeId: node.id,
    name: node.name,
    region: node.region,
    realAvailRamMB: Math.round((total - used) / (1024 * 1024)),
    realTotalRamMB: Math.round(total / (1024 * 1024)),
    committedRamMB,
    capacityRamMB: node.capacityRamMB,
    poolFreeBytes: Number(storage?.avail ?? 0),
    poolTotalBytes: Number(storage?.total ?? 0),
    cpuThreads: Number(status?.cpuinfo?.cpus ?? 0),
    committedVcpu,
    cpuLoad: Number(status?.cpu ?? 0),
  };
}

