/** Is phase `p` already complete according to the checkpoints? */
export function phaseComplete(p: MovePhase, cp: MoveCheckpoints, opts: { dedicated: boolean }): boolean {
  switch (p) {
    case "PREFLIGHT":
      return true; // a VmMove row with a plan exists by the time the worker runs
    case "SNAPSHOT_LIVE":
      return !!cp.liveSnapshotName;
    case "SEND_FULL":
      return !!cp.fullSentAt;
    case "STOP_SOURCE":
      return !!cp.sourceStoppedAt;
    case "SEND_INCREMENTAL":
      return !!cp.incrementalSentAt;
    case "CREATE_TARGET":
      return !!cp.targetVmCreated;
    case "MOVE_IP":
      return opts.dedicated ? !!cp.ipMovedAt : true;
    case "START_TARGET":
      return !!cp.targetVerified;
    case "COMMIT":
      return !!cp.committedAt;
    case "DONE":
      return !!cp.committedAt;
  }
}

/** The first phase a (resumed) run still has to execute. */
export function nextPhase(cp: MoveCheckpoints, opts: { dedicated: boolean }): MovePhase {
  for (const p of MOVE_PHASES) {
    if (p === "PREFLIGHT") continue;
    if (!phaseComplete(p, cp, opts)) return p;
  }
  return "DONE";
}

/** Phases that may be rolled back automatically (anything before COMMIT). Once
 *  COMMIT has run the DB points at the target; from there forward is the only
 *  safe direction and a human decides. */
export function rollbackAllowed(cp: MoveCheckpoints): boolean {
  return !cp.committedAt;
}

/** What rollback must undo, in order, given what the checkpoints say exists.
 *  Pure so the exact inventory is testable; the worker executes each step and
